  // ═══════════════════════════════════════════════════════════════
  // 2. GAME GENERATORS (5 types)
  // ═══════════════════════════════════════════════════════════════
  function generatePlayableGame(specs) {
    var f = specs.features;
    if (f.hasPuzzle) return generatePuzzleGame(specs);
    if (f.hasPlatformer) return generatePlatformerGame(specs);
    if (f.hasRPG) return generateRPGGame(specs);
    if (f.hasRacing) return generateRacingGame(specs);
    return generateShooterGame(specs);
  }

  function generateShooterGame(specs) {
    return sharedHead(specs, 'Space Shooter') + '\n  <style>\n    body { display: flex; flex-direction: column; align-items: center; justify-content: center; min-height: 100vh; padding: 1rem; user-select: none; overflow: hidden; }\n    .game-header { display: flex; justify-content: space-between; align-items: center; width: 100%; max-width: 720px; margin-bottom: 0.6rem; }\n    .game-title { font-size: 1.1rem; font-weight: 900; color: ' + specs.primaryColor + '; text-shadow: 0 0 12px ' + specs.primaryColor + '44; text-transform: uppercase; letter-spacing: 0.05em; display: flex; align-items: center; gap: 0.5rem; }\n    .hud { display: flex; gap: 0.75rem; font-family: \'JetBrains Mono\', monospace; font-size: 0.85rem; }\n    .hud-box { background: rgba(255,255,255,0.06); padding: 0.25rem 0.7rem; border-radius: 6px; border: 1px solid ' + specs.primaryColor + '44; backdrop-filter: blur(8px); }\n    .canvas-wrap { border-radius: 12px; overflow: hidden; box-shadow: 0 0 40px rgba(0,0,0,0.9), 0 0 20px ' + specs.primaryColor + '33; border: 2px solid ' + specs.primaryColor + '55; }\n    canvas { display: block; background: #04050a; cursor: crosshair; }\n    .hint { margin-top: 0.7rem; font-size: 0.75rem; color: #64748b; font-family: \'JetBrains Mono\', monospace; text-align: center; }\n    .btn-restart { margin-top: 0.4rem; padding: 0.5rem 1.3rem; background: linear-gradient(135deg, ' + specs.gradientStart + ', ' + specs.gradientEnd + '); color: #000; border: none; border-radius: 8px; font-weight: 800; font-size: 0.85rem; cursor: pointer; text-transform: uppercase; transition: transform 0.2s, box-shadow 0.2s; }\n    .btn-restart:hover { transform: translateY(-2px); box-shadow: 0 4px 15px ' + specs.primaryColor + '44; }\n  </style>\n</head>\n<body>\n  <div class="game-header">\n    <div class="game-title">' + icons.gamepad + ' ' + specs.title + '</div>\n    <div class="hud">\n      <div class="hud-box">SCORE: <span id="score">0</span></div>\n      <div class="hud-box">LEVEL: <span id="level">1</span></div>\n      <div class="hud-box">LIVES: <span id="lives">3</span></div>\n      <div class="hud-box">COMBO: <span id="combo">x1</span></div>\n    </div>\n  </div>\n  <div class="canvas-wrap"><canvas id="gc" width="700" height="420"></canvas></div>\n  <div class="hint">Arrow Keys / WASD = Move | SPACEBAR / Click = Fire | Survive and score!</div>\n  <button class="btn-restart" onclick="resetGame()">Restart</button>\n  ' + aiBadge(specs) + '\n  <script>\n    var canvas=document.getElementById("gc"),ctx=canvas.getContext("2d");\n    var scoreEl=document.getElementById("score"),levelEl=document.getElementById("level"),livesEl=document.getElementById("lives"),comboEl=document.getElementById("combo");\n    var score=0,level=1,lives=3,gameOver=false,combo=1,comboTimer=0,screenShake=0;\n    var player={x:canvas.width/2-15,y:canvas.height-50,w:30,h:30,speed:6,color:"' + specs.primaryColor + '",shield:false,shieldTimer:0};\n    var keys={},bullets=[],enemies=[],particles=[],powerups=[],stars=[];\n    for(var i=0;i<60;i++)stars.push({x:Math.random()*canvas.width,y:Math.random()*canvas.height,s:Math.random()*1.5+0.5,sp:Math.random()*0.5+0.2});\n    window.addEventListener("keydown",function(e){keys[e.code]=true;if(e.code==="Space"){e.preventDefault();fire();}});\n    window.addEventListener("keyup",function(e){keys[e.code]=false;});\n    canvas.addEventListener("click",fire);\n    function fire(){if(gameOver)return;bullets.push({x:player.x+player.w/2-3,y:player.y,w:6,h:14,sp:10,c:"' + specs.accentColor + '"});}\n    var spawnRate=1000,spawnTimer=0,lastTime=performance.now();\n    function spawnEnemy(){if(gameOver)return;var sz=Math.random()*20+18,sp=Math.random()*1.5+1+level*0.25;var isBoss=level>=5&&Math.random()<0.08;if(isBoss){enemies.push({x:Math.random()*(canvas.width-50),y:-50,w:50,h:50,sp:sp*0.5,c:"#ff007f",hp:5,boss:true});}else{enemies.push({x:Math.random()*(canvas.width-sz),y:-sz,w:sz,h:sz,sp:sp,c:level>3?"#ff007f":"#ff0055",hp:1,boss:false});}}\n    function explode(x,y,c,n){for(var i=0;i<(n||15);i++)particles.push({x:x,y:y,vx:(Math.random()-0.5)*8,vy:(Math.random()-0.5)*8,r:Math.random()*3+1,a:1,c:c});}\n    function update(dt){if(gameOver)return;if((keys.ArrowLeft||keys.KeyA)&&player.x>0)player.x-=player.speed;if((keys.ArrowRight||keys.KeyD)&&player.x<canvas.width-player.w)player.x+=player.speed;if((keys.ArrowUp||keys.KeyW)&&player.y>0)player.y-=player.speed;if((keys.ArrowDown||keys.KeyS)&&player.y<canvas.height-player.h)player.y+=player.speed;if(player.shield){player.shieldTimer-=dt;if(player.shieldTimer<=0)player.shield=false;}if(comboTimer>0){comboTimer-=dt;if(comboTimer<=0){combo=1;comboEl.textContent="x1";}}if(screenShake>0)screenShake-=dt;for(var i=bullets.length-1;i>=0;i--){bullets[i].y-=bullets[i].sp;if(bullets[i].y<0)bullets.splice(i,1);}if(Math.random()<0.005){var type=Math.random()<0.5?"life":"shield";powerups.push({x:Math.random()*(canvas.width-16),y:-16,w:16,h:16,sp:2,type:type});}for(var i=powerups.length-1;i>=0;i--){powerups[i].y+=powerups[i].sp;if(player.x<powerups[i].x+16&&player.x+player.w>powerups[i].x&&player.y<powerups[i].y+16&&player.y+player.h>powerups[i].y){if(powerups[i].type==="life"){lives=Math.min(lives+1,5);livesEl.textContent=lives;}else{player.shield=true;player.shieldTimer=5000;}powerups.splice(i,1);continue;}if(powerups[i].y>canvas.height)powerups.splice(i,1);}spawnTimer+=dt;spawnRate=Math.max(350,1000-level*80);if(spawnTimer>=spawnRate){spawnEnemy();spawnTimer=0;}for(var i=enemies.length-1;i>=0;i--){var e=enemies[i];e.y+=e.sp;if(player.x<e.x+e.w&&player.x+player.w>e.x&&player.y<e.y+e.h&&player.y+player.h>e.y){if(player.shield){explode(e.x+e.w/2,e.y+e.h/2,"' + specs.primaryColor + '",20);enemies.splice(i,1);score+=50*combo;scoreEl.textContent=score;continue;}explode(player.x+player.w/2,player.y+player.h/2,"#ff0055",25);enemies.splice(i,1);lives--;livesEl.textContent=lives;screenShake=200;combo=1;comboEl.textContent="x1";if(lives<=0)gameOver=true;continue;}for(var j=bullets.length-1;j>=0;j--){var b=bullets[j];if(b.x<e.x+e.w&&b.x+b.w>e.x&&b.y<e.y+e.h&&b.y+b.h>e.y){e.hp--;bullets.splice(j,1);if(e.hp<=0){explode(e.x+e.w/2,e.y+e.h/2,e.boss?"#ff007f":"' + specs.primaryColor + '",e.boss?30:15);enemies.splice(i,1);var pts=e.boss?500:100;score+=pts*combo;scoreEl.textContent=score;combo++;comboTimer=2000;comboEl.textContent="x"+combo;if(score>0&&score%(level<5?500:1000)===0){level++;levelEl.textContent=level;}}break;}}if(e&&e.y>canvas.height)enemies.splice(i,1);}for(var i=particles.length-1;i>=0;i--){var p=particles[i];p.x+=p.vx;p.y+=p.vy;p.a-=0.025;if(p.a<=0)particles.splice(i,1);}for(var k=0;k<stars.length;k++){stars[k].y+=stars[k].sp;if(stars[k].y>canvas.height){stars[k].y=0;stars[k].x=Math.random()*canvas.width;}}}\n    function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);ctx.save();if(screenShake>0){var sx=(Math.random()-0.5)*6,sy=(Math.random()-0.5)*6;ctx.translate(sx,sy);}ctx.fillStyle="rgba(255,255,255,0.4)";for(var k=0;k<stars.length;k++)ctx.fillRect(stars[k].x,stars[k].y,stars[k].s,stars[k].s);if(!gameOver){if(player.shield){ctx.strokeStyle="' + specs.primaryColor + '";ctx.lineWidth=2;ctx.globalAlpha=0.5+Math.sin(Date.now()/200)*0.3;ctx.beginPath();ctx.arc(player.x+player.w/2,player.y+player.h/2,24,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;}ctx.fillStyle=player.color;ctx.shadowColor=player.color;ctx.shadowBlur=15;ctx.beginPath();ctx.moveTo(player.x+player.w/2,player.y);ctx.lineTo(player.x+player.w,player.y+player.h);ctx.lineTo(player.x,player.y+player.h);ctx.closePath();ctx.fill();ctx.shadowBlur=0;for(var i=0;i<bullets.length;i++){ctx.fillStyle=bullets[i].c;ctx.shadowColor=bullets[i].c;ctx.shadowBlur=8;ctx.fillRect(bullets[i].x,bullets[i].y,bullets[i].w,bullets[i].h);ctx.shadowBlur=0;}for(var i=0;i<enemies.length;i++){var e=enemies[i];ctx.fillStyle=e.c;ctx.shadowColor=e.c;ctx.shadowBlur=10;if(e.boss){ctx.beginPath();ctx.moveTo(e.x+e.w/2,e.y+e.h);ctx.lineTo(e.x,e.y);ctx.lineTo(e.x+e.w,e.y);ctx.closePath();ctx.fill();}else ctx.fillRect(e.x,e.y,e.w,e.h);ctx.shadowBlur=0;if(e.boss&&e.hp>0){ctx.fillStyle="#333";ctx.fillRect(e.x,e.y-8,e.w,4);ctx.fillStyle="#ff007f";ctx.fillRect(e.x,e.y-8,e.w*(e.hp/5),4);}}for(var i=0;i<powerups.length;i++){var p=powerups[i];ctx.fillStyle=p.type==="life"?"#10b981":"#38bdf8";ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=8;ctx.beginPath();ctx.arc(p.x+8,p.y+8,8,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle="#000";ctx.font="bold 10px Inter";ctx.textAlign="center";ctx.fillText(p.type==="life"?"+":"S",p.x+8,p.y+12);}}else{ctx.fillStyle="' + specs.primaryColor + '";ctx.font="900 36px Inter";ctx.textAlign="center";ctx.fillText("GAME OVER",canvas.width/2,canvas.height/2-15);ctx.fillStyle="#94a3b8";ctx.font=\'14px "JetBrains Mono"\';ctx.fillText("Score: "+score+" | Level: "+level+" | Best Combo: x"+combo,canvas.width/2,canvas.height/2+20);}for(var i=0;i<particles.length;i++){var p=particles[i];ctx.save();ctx.globalAlpha=p.a;ctx.fillStyle=p.c;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();ctx.restore();}ctx.restore();}\n    function loop(t){var dt=t-lastTime;lastTime=t;update(dt);draw();requestAnimationFrame(loop);}\n    function resetGame(){score=0;level=1;lives=3;gameOver=false;combo=1;comboTimer=0;screenShake=0;player.shield=false;scoreEl.textContent="0";levelEl.textContent="1";livesEl.textContent="3";comboEl.textContent="x1";enemies.length=0;bullets.length=0;particles.length=0;powerups.length=0;player.x=canvas.width/2-15;player.y=canvas.height-50;}\n    requestAnimationFrame(loop);\n  <\/script>\n</body>\n</html>';
  }

  function generatePuzzleGame(specs) {
    return sharedHead(specs, 'Memory Puzzle') + '\n  <style>\n    body { display: flex; flex-direction: column; align-items: center; justify-content: center; min-height: 100vh; padding: 1rem; }\n    h2 { color: ' + specs.primaryColor + '; margin-bottom: 0.6rem; text-transform: uppercase; font-size: 1.2rem; letter-spacing: 0.05em; display: flex; align-items: center; gap: 0.5rem; }\n    .grid { display: grid; grid-template-columns: repeat(4, 72px); gap: 10px; margin-bottom: 1rem; perspective: 600px; }\n    .cell { width: 72px; height: 72px; border-radius: 12px; display: flex; align-items: center; justify-content: center; font-size: 1.5rem; font-weight: 900; cursor: pointer; transition: transform 0.4s ease, box-shadow 0.3s; border: 2px solid rgba(255,255,255,0.08); user-select: none; }\n    .cell:hover:not(.matched) { transform: scale(1.06); box-shadow: 0 0 20px ' + specs.primaryColor + '44; }\n    .cell.matched { opacity: 0.25; pointer-events: none; border-color: ' + specs.primaryColor + '; transform: scale(0.9); }\n    .cell.flipped { background: linear-gradient(135deg, ' + specs.gradientStart + ', ' + specs.gradientEnd + '); color: #000; border-color: ' + specs.primaryColor + '; }\n    .cell.face-down { background: rgba(255,255,255,0.06); color: transparent; backdrop-filter: blur(4px); }\n    .hud { font-family: \'JetBrains Mono\', monospace; font-size: 0.9rem; margin-bottom: 1rem; display: flex; gap: 1.2rem; }\n    .hud span { background: rgba(255,255,255,0.06); padding: 0.3rem 0.75rem; border-radius: 8px; border: 1px solid ' + specs.primaryColor + '33; }\n    .timer { color: ' + specs.accentColor + '; }\n    .btn { padding: 0.5rem 1.3rem; background: linear-gradient(135deg, ' + specs.gradientStart + ', ' + specs.gradientEnd + '); color: #000; border: none; border-radius: 8px; font-weight: 800; cursor: pointer; text-transform: uppercase; font-size: 0.85rem; transition: transform 0.2s; }\n    .btn:hover { transform: translateY(-2px); }\n  </style>\n</head>\n<body>\n  <h2>' + icons.gamepad + ' ' + specs.title + '</h2>\n  <div class="hud"><span>Moves: <b id="moves">0</b></span><span>Pairs: <b id="pairs">0</b>/8</span><span class="timer">Time: <b id="timer">0</b>s</span></div>\n  <div class="grid" id="grid"></div>\n  <button class="btn" onclick="initGame()">New Game</button>\n  ' + aiBadge(specs) + '\n  <script>\n    var symbols=["A","B","C","D","E","F","G","H"];\n    var grid=document.getElementById("grid");\n    var cards=[],flipped=[],matched=0,moves=0,locked=false,timerVal=0,timerID;\n    function initGame(){matched=0;moves=0;flipped=[];locked=false;timerVal=0;document.getElementById("moves").textContent="0";document.getElementById("pairs").textContent="0";document.getElementById("timer").textContent="0";clearInterval(timerID);timerID=setInterval(function(){timerVal++;document.getElementById("timer").textContent=timerVal;},1000);var deck=symbols.concat(symbols).sort(function(){return Math.random()-0.5;});cards=deck;grid.innerHTML="";deck.forEach(function(sym,i){var cell=document.createElement("div");cell.className="cell face-down fade-in";cell.dataset.idx=i;cell.textContent=sym;cell.onclick=function(){flipCard(cell,i);};cell.style.animationDelay=(i*0.05)+"s";grid.appendChild(cell);});}\n    function flipCard(cell,idx){if(locked||flipped.length>=2||cell.classList.contains("flipped")||cell.classList.contains("matched"))return;cell.classList.remove("face-down");cell.classList.add("flipped");flipped.push({cell:cell,idx:idx});if(flipped.length===2){moves++;document.getElementById("moves").textContent=moves;locked=true;if(cards[flipped[0].idx]===cards[flipped[1].idx]){flipped[0].cell.classList.add("matched");flipped[1].cell.classList.add("matched");matched++;document.getElementById("pairs").textContent=matched;flipped=[];locked=false;if(matched===8){clearInterval(timerID);setTimeout(function(){alert("Complete in "+moves+" moves, "+timerVal+"s!");},300);}}else{setTimeout(function(){flipped[0].cell.classList.remove("flipped");flipped[0].cell.classList.add("face-down");flipped[1].cell.classList.remove("flipped");flipped[1].cell.classList.add("face-down");flipped=[];locked=false;},700);}}}\n    initGame();\n  <\/script>\n</body>\n</html>';
  }

  function generatePlatformerGame(specs) {
    return sharedHead(specs, 'Platformer') + '\n  <style>\n    body { display: flex; flex-direction: column; align-items: center; justify-content: center; min-height: 100vh; padding: 1rem; user-select: none; }\n    .hud { display: flex; gap: 1rem; margin-bottom: 0.5rem; font-family: \'JetBrains Mono\', monospace; font-size: 0.85rem; width: 100%; max-width: 720px; justify-content: space-between; }\n    .hud span { color: ' + specs.primaryColor + '; font-weight: 700; }\n    .canvas-wrap { border-radius: 12px; overflow: hidden; box-shadow: 0 0 30px rgba(0,0,0,0.8), 0 0 15px ' + specs.primaryColor + '33; border: 2px solid ' + specs.primaryColor + '55; }\n    canvas { display: block; background: linear-gradient(180deg, #0a0e17, #141a2e); }\n    .hint { margin-top: 0.6rem; font-size: 0.72rem; color: #64748b; font-family: \'JetBrains Mono\', monospace; }\n    .btn { margin-top: 0.4rem; padding: 0.5rem 1.2rem; background: linear-gradient(135deg, ' + specs.gradientStart + ', ' + specs.gradientEnd + '); color: #000; border: none; border-radius: 8px; font-weight: 800; cursor: pointer; text-transform: uppercase; font-size: 0.85rem; }\n  </style>\n</head>\n<body>\n  <div class="hud"><span>' + specs.title + '</span><span>Score: <b id="sc">0</b></span><span>Coins: <b id="coins">0</b></span><span>Jumps: <b id="jc">2</b></span></div>\n  <div class="canvas-wrap"><canvas id="c" width="700" height="380"></canvas></div>\n  <div class="hint">Arrow Keys = Move | UP / SPACE = Jump (Double Jump!) | Collect coins, avoid red zones</div>\n  <button class="btn" onclick="restart()">Restart</button>\n  ' + aiBadge(specs) + '\n  <script>\n    var c=document.getElementById("c"),ctx=c.getContext("2d"),scEl=document.getElementById("sc"),coinsEl=document.getElementById("coins"),jcEl=document.getElementById("jc");\n    var P={x:60,y:300,w:24,h:28,vy:0,vx:0,onGround:false,jumpsLeft:2,color:"' + specs.primaryColor + '"};\n    var score=0,coins=0,cameraX=0,gameOver=false;\n    var keys={},trail=[];\n    var G=0.6,JUMP=-11,SPEED=5,MAX_JUMPS=2;\n    var platforms=[];for(var i=0;i<40;i++){var px=i*200+100,py=280-Math.sin(i*0.4)*70+Math.random()*30;var moving=i>5&&Math.random()<0.2;platforms.push({x:px,y:py,w:130+Math.random()*50,h:14,moving:moving,dir:1,range:40,origY:py});}platforms.unshift({x:0,y:320,w:300,h:20,moving:false});\n    var coinList=[];platforms.forEach(function(p){if(Math.random()>0.25)coinList.push({x:p.x+p.w/2-6,y:p.y-30,w:12,h:12,collected:false});});\n    var hazards=[];for(var i=8;i<40;i+=5){var p=platforms[i];if(p)hazards.push({x:p.x+20,y:p.y-12,w:p.w-40,h:12});}\n    window.addEventListener("keydown",function(e){keys[e.code]=true;if(e.code==="Space")e.preventDefault();});\n    window.addEventListener("keyup",function(e){keys[e.code]=false;});\n    function update(){if(gameOver)return;if(keys.ArrowLeft||keys.KeyA)P.vx=-SPEED;else if(keys.ArrowRight||keys.KeyD)P.vx=SPEED;else P.vx*=0.75;if((keys.ArrowUp||keys.Space||keys.KeyW)&&P.jumpsLeft>0&&!keys._jumped){P.vy=JUMP;P.jumpsLeft--;jcEl.textContent=P.jumpsLeft;keys._jumped=true;}if(!(keys.ArrowUp||keys.Space||keys.KeyW))keys._jumped=false;P.vy+=G;P.x+=P.vx;P.y+=P.vy;P.onGround=false;for(var i=0;i<platforms.length;i++){var pl=platforms[i];if(pl.moving){pl.y+=pl.dir*0.5;if(Math.abs(pl.y-pl.origY)>pl.range)pl.dir*=-1;}if(P.x+P.w>pl.x&&P.x<pl.x+pl.w&&P.y+P.h>pl.y&&P.y+P.h<pl.y+pl.h+12&&P.vy>=0){P.y=pl.y-P.h;P.vy=0;P.onGround=true;P.jumpsLeft=MAX_JUMPS;jcEl.textContent=P.jumpsLeft;}}for(var i=0;i<hazards.length;i++){var h=hazards[i];if(P.x+P.w>h.x&&P.x<h.x+h.w&&P.y+P.h>h.y&&P.y<h.y+h.h)gameOver=true;}if(P.y>c.height+80)gameOver=true;cameraX=P.x-200;for(var i=0;i<coinList.length;i++){var co=coinList[i];if(!co.collected&&P.x+P.w>co.x&&P.x<co.x+co.w&&P.y+P.h>co.y&&P.y<co.y+co.h){co.collected=true;coins++;score+=50;coinsEl.textContent=coins;scEl.textContent=score;}}trail.push({x:P.x+P.w/2,y:P.y+P.h,a:0.6});if(trail.length>20)trail.shift();for(var i=0;i<trail.length;i++)trail[i].a-=0.03;}\n    function draw(){ctx.clearRect(0,0,c.width,c.height);ctx.save();ctx.translate(-cameraX,0);for(var i=0;i<trail.length;i++){if(trail[i].a>0){ctx.globalAlpha=trail[i].a;ctx.fillStyle="' + specs.primaryColor + '";ctx.beginPath();ctx.arc(trail[i].x,trail[i].y,3,0,Math.PI*2);ctx.fill();}}ctx.globalAlpha=1;ctx.fillStyle=P.color;ctx.shadowColor=P.color;ctx.shadowBlur=12;ctx.fillRect(P.x,P.y,P.w,P.h);ctx.shadowBlur=0;ctx.fillStyle="#000";ctx.fillRect(P.x+5,P.y+6,4,4);ctx.fillRect(P.x+15,P.y+6,4,4);for(var i=0;i<platforms.length;i++){var pl=platforms[i];ctx.fillStyle=pl.moving?"rgba(255,255,255,0.2)":"rgba(255,255,255,0.12)";ctx.fillRect(pl.x,pl.y,pl.w,pl.h);if(pl.moving){ctx.strokeStyle="' + specs.primaryColor + '44";ctx.lineWidth=1;ctx.strokeRect(pl.x,pl.y,pl.w,pl.h);}}ctx.fillStyle="#ff004422";ctx.strokeStyle="#ff0044";ctx.lineWidth=1;for(var i=0;i<hazards.length;i++){ctx.fillRect(hazards[i].x,hazards[i].y,hazards[i].w,hazards[i].h);ctx.strokeRect(hazards[i].x,hazards[i].y,hazards[i].w,hazards[i].h);}for(var i=0;i<coinList.length;i++){if(!coinList[i].collected){ctx.fillStyle="#ffd700";ctx.shadowColor="#ffd700";ctx.shadowBlur=6;ctx.beginPath();ctx.arc(coinList[i].x+6,coinList[i].y+6,6,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;}}ctx.restore();if(gameOver){ctx.fillStyle="' + specs.primaryColor + '";ctx.font="900 32px Inter";ctx.textAlign="center";ctx.fillText("FELL OFF!",c.width/2,c.height/2);ctx.fillStyle="#94a3b8";ctx.font=\'14px "JetBrains Mono"\';ctx.fillText("Score: "+score+" | Press Restart",c.width/2,c.height/2+28);}}\n    function loop(){update();draw();requestAnimationFrame(loop);}\n    function restart(){P.x=60;P.y=300;P.vy=0;P.vx=0;P.jumpsLeft=2;score=0;coins=0;gameOver=false;scEl.textContent="0";coinsEl.textContent="0";jcEl.textContent="2";coinList.forEach(function(c){c.collected=false;});trail.length=0;}\n    loop();\n  <\/script>\n</body>\n</html>';
  }

  function generateRPGGame(specs) {
    return sharedHead(specs, 'RPG Adventure') + '\n  <style>\n    body { display: flex; flex-direction: column; align-items: center; justify-content: center; min-height: 100vh; padding: 1rem; user-select: none; }\n    .hud { display: flex; gap: 0.6rem; margin-bottom: 0.5rem; font-family: \'JetBrains Mono\', monospace; font-size: 0.8rem; width: 100%; max-width: 520px; justify-content: space-between; }\n    .hud-item { background: rgba(255,255,255,0.06); padding: 0.25rem 0.6rem; border-radius: 6px; border: 1px solid ' + specs.primaryColor + '33; }\n    .hp-bar { width: 100px; height: 8px; background: #333; border-radius: 4px; display: inline-block; vertical-align: middle; overflow: hidden; }\n    .hp-fill { height: 100%; background: linear-gradient(90deg, #ff0044, #10b981); border-radius: 4px; transition: width 0.3s; }\n    .canvas-wrap { border-radius: 12px; overflow: hidden; box-shadow: 0 0 30px rgba(0,0,0,0.8), 0 0 12px ' + specs.primaryColor + '33; border: 2px solid ' + specs.primaryColor + '44; }\n    canvas { display: block; image-rendering: pixelated; }\n    .hint { margin-top: 0.5rem; font-size: 0.72rem; color: #64748b; font-family: \'JetBrains Mono\', monospace; }\n    .log { margin-top: 0.5rem; width: 100%; max-width: 520px; height: 60px; overflow-y: auto; background: rgba(0,0,0,0.4); border-radius: 8px; padding: 0.4rem 0.6rem; font-family: \'JetBrains Mono\', monospace; font-size: 0.7rem; color: #94a3b8; border: 1px solid rgba(255,255,255,0.06); }\n  </style>\n</head>\n<body>\n  <div class="hud">\n    <div class="hud-item">HP: <div class="hp-bar"><div class="hp-fill" id="hpBar" style="width:100%"></div></div></div>\n    <div class="hud-item">LVL: <b id="lvl">1</b></div>\n    <div class="hud-item">XP: <b id="xp">0</b>/100</div>\n    <div class="hud-item">Gold: <b id="gold">0</b></div>\n    <div class="hud-item">Kills: <b id="kills">0</b></div>\n  </div>\n  <div class="canvas-wrap"><canvas id="gc" width="512" height="384"></canvas></div>\n  <div class="hint">WASD / Arrow Keys = Move | SPACE = Attack | Defeat enemies, collect loot, level up!</div>\n  <div class="log" id="log"></div>\n  ' + aiBadge(specs) + '\n  <script>\n    var c=document.getElementById("gc"),ctx=c.getContext("2d"),TILE=32,COLS=16,ROWS=12;\n    var hpBar=document.getElementById("hpBar"),lvlEl=document.getElementById("lvl"),xpEl=document.getElementById("xp"),goldEl=document.getElementById("gold"),killsEl=document.getElementById("kills"),logEl=document.getElementById("log");\n    var hero={x:3,y:3,hp:100,maxHp:100,atk:15,lvl:1,xp:0,gold:0,kills:0,color:"' + specs.primaryColor + '",attackCooldown:0};\n    var keys={},enemies=[],loot=[],particles=[];\n    var map=[];for(var r=0;r<ROWS;r++){map[r]=[];for(var c2=0;c2<COLS;c2++){map[r][c2]=(r===0||r===ROWS-1||c2===0||c2===COLS-1)?1:(Math.random()<0.15?1:0);}}map[hero.y][hero.x]=0;map[hero.y+1][hero.x]=0;\n    function spawnEnemies(){enemies=[];for(var i=0;i<5+hero.lvl*2;i++){var ex,ey;do{ex=Math.floor(Math.random()*(COLS-2))+1;ey=Math.floor(Math.random()*(ROWS-2))+1;}while(map[ey][ex]===1||(ex===hero.x&&ey===hero.y));enemies.push({x:ex,y:ey,hp:20+hero.lvl*5,maxHp:20+hero.lvl*5,atk:5+hero.lvl*2,color:"#ff0055"});}}\n    function spawnLoot(){for(var i=0;i<3;i++){var lx,ly;do{lx=Math.floor(Math.random()*(COLS-2))+1;ly=Math.floor(Math.random()*(ROWS-2))+1;}while(map[ly][lx]===1);loot.push({x:lx,y:ly,type:Math.random()<0.4?"hp":"gold",collected:false});}}\n    spawnEnemies();spawnLoot();\n    function addLog(msg){logEl.innerHTML+="<div>"+msg+"</div>";logEl.scrollTop=logEl.scrollHeight;}addLog("Welcome, adventurer. Explore the dungeon!");\n    window.addEventListener("keydown",function(e){if(keys[e.code])return;keys[e.code]=true;var dx=0,dy=0;if(e.code==="ArrowUp"||e.code==="KeyW")dy=-1;if(e.code==="ArrowDown"||e.code==="KeyS")dy=1;if(e.code==="ArrowLeft"||e.code==="KeyA")dx=-1;if(e.code==="ArrowRight"||e.code==="KeyD")dx=1;if(e.code==="Space"){attack();e.preventDefault();return;}var nx=hero.x+dx,ny=hero.y+dy;if(nx>=0&&nx<COLS&&ny>=0&&ny<ROWS&&map[ny][nx]===0){var blocked=enemies.some(function(en){return en.x===nx&&en.y===ny;});if(!blocked){hero.x=nx;hero.y=ny;checkLoot();moveEnemies();}}});\n    window.addEventListener("keyup",function(e){keys[e.code]=false;});\n    function attack(){if(hero.attackCooldown>0)return;hero.attackCooldown=300;var hit=false;for(var i=enemies.length-1;i>=0;i--){var e=enemies[i];if(Math.abs(e.x-hero.x)<=1&&Math.abs(e.y-hero.y)<=1){var dmg=hero.atk+Math.floor(Math.random()*5);e.hp-=dmg;for(var p=0;p<8;p++)particles.push({x:e.x*TILE+TILE/2,y:e.y*TILE+TILE/2,vx:(Math.random()-0.5)*6,vy:(Math.random()-0.5)*6,a:1,c:"' + specs.primaryColor + '"});addLog("Hit enemy for <span style=\\"color:' + specs.primaryColor + '\\">"+dmg+"</span> damage!");if(e.hp<=0){enemies.splice(i,1);hero.kills++;killsEl.textContent=hero.kills;var xpGain=15+hero.lvl*5;hero.xp+=xpGain;xpEl.textContent=hero.xp;var goldGain=Math.floor(Math.random()*10)+5;hero.gold+=goldGain;goldEl.textContent=hero.gold;addLog("Enemy defeated! +"+xpGain+" XP, +"+goldGain+" Gold");if(hero.xp>=hero.lvl*100){hero.lvl++;hero.maxHp+=20;hero.hp=hero.maxHp;hero.atk+=5;hero.xp=0;lvlEl.textContent=hero.lvl;xpEl.textContent="0";addLog("<span style=\\"color:#ffd700\\">LEVEL UP! You are now level "+hero.lvl+"!</span>");}if(enemies.length===0){addLog("<span style=\\"color:#10b981\\">Floor cleared! New enemies spawning...</span>");spawnEnemies();spawnLoot();}}hit=true;}}if(!hit)addLog("Swing and miss...");}\n    function moveEnemies(){for(var i=0;i<enemies.length;i++){var e=enemies[i];if(Math.abs(e.x-hero.x)<=1&&Math.abs(e.y-hero.y)<=1){var dmg=e.atk+Math.floor(Math.random()*3);hero.hp-=dmg;hpBar.style.width=(hero.hp/hero.maxHp*100)+"%";addLog("<span style=\\"color:#ff0055\\">Enemy hits you for "+dmg+" damage!</span>");if(hero.hp<=0){hero.hp=0;addLog("<span style=\\"color:#ff0055\\">You have fallen! Refresh to restart.</span>");}continue;}if(Math.random()<0.5){var dx2=Math.sign(hero.x-e.x),dy2=Math.sign(hero.y-e.y);var nx2=e.x+dx2,ny2=e.y+dy2;if(nx2>=0&&nx2<COLS&&ny2>=0&&ny2<ROWS&&map[ny2][nx2]===0&&!(nx2===hero.x&&ny2===hero.y)&&!enemies.some(function(oe){return oe!==e&&oe.x===nx2&&oe.y===ny2;})){e.x=nx2;e.y=ny2;}}}}\n    function checkLoot(){for(var i=0;i<loot.length;i++){var l=loot[i];if(!l.collected&&l.x===hero.x&&l.y===hero.y){l.collected=true;if(l.type==="hp"){var heal=25;hero.hp=Math.min(hero.hp+heal,hero.maxHp);hpBar.style.width=(hero.hp/hero.maxHp*100)+"%";addLog("<span style=\\"color:#10b981\\">Found healing potion! +"+heal+" HP</span>");}else{var g=Math.floor(Math.random()*15)+10;hero.gold+=g;goldEl.textContent=hero.gold;addLog("<span style=\\"color:#ffd700\\">Found "+g+" gold!</span>");}}}}\n    function draw(){ctx.clearRect(0,0,c.width,c.height);for(var r=0;r<ROWS;r++)for(var cl=0;cl<COLS;cl++){ctx.fillStyle=map[r][cl]===1?"#1a1a2e":"#0d0d1a";ctx.fillRect(cl*TILE,r*TILE,TILE,TILE);if(map[r][cl]===1){ctx.strokeStyle="#252540";ctx.lineWidth=1;ctx.strokeRect(cl*TILE,r*TILE,TILE,TILE);}}for(var i=0;i<loot.length;i++){var l=loot[i];if(!l.collected){ctx.fillStyle=l.type==="hp"?"#10b981":"#ffd700";ctx.beginPath();ctx.arc(l.x*TILE+TILE/2,l.y*TILE+TILE/2,6,0,Math.PI*2);ctx.fill();}}for(var i=0;i<enemies.length;i++){var e=enemies[i];ctx.fillStyle=e.color;ctx.shadowColor=e.color;ctx.shadowBlur=8;ctx.fillRect(e.x*TILE+4,e.y*TILE+4,TILE-8,TILE-8);ctx.shadowBlur=0;ctx.fillStyle="#333";ctx.fillRect(e.x*TILE+4,e.y*TILE,TILE-8,3);ctx.fillStyle=e.color;ctx.fillRect(e.x*TILE+4,e.y*TILE,(TILE-8)*(e.hp/e.maxHp),3);}ctx.fillStyle=hero.hp>0?hero.color:"#333";ctx.shadowColor=hero.color;ctx.shadowBlur=hero.hp>0?12:0;ctx.fillRect(hero.x*TILE+2,hero.y*TILE+2,TILE-4,TILE-4);ctx.shadowBlur=0;ctx.fillStyle="#000";ctx.fillRect(hero.x*TILE+8,hero.y*TILE+10,4,4);ctx.fillRect(hero.x*TILE+20,hero.y*TILE+10,4,4);for(var i=particles.length-1;i>=0;i--){var p=particles[i];p.x+=p.vx;p.y+=p.vy;p.a-=0.04;ctx.globalAlpha=p.a;ctx.fillStyle=p.c;ctx.beginPath();ctx.arc(p.x,p.y,2,0,Math.PI*2);ctx.fill();if(p.a<=0)particles.splice(i,1);}ctx.globalAlpha=1;if(hero.attackCooldown>0)hero.attackCooldown-=16;}\n    function loop(){draw();requestAnimationFrame(loop);}loop();\n  <\/script>\n</body>\n</html>';
  }

  function generateRacingGame(specs) {
    return sharedHead(specs, 'Racing') + '\n  <style>\n    body { display: flex; flex-direction: column; align-items: center; justify-content: center; min-height: 100vh; padding: 1rem; user-select: none; overflow: hidden; }\n    .hud { display: flex; gap: 1rem; margin-bottom: 0.5rem; font-family: \'JetBrains Mono\', monospace; font-size: 0.85rem; width: 100%; max-width: 520px; justify-content: space-between; }\n    .hud span { color: ' + specs.primaryColor + '; font-weight: 700; }\n    .canvas-wrap { border-radius: 12px; overflow: hidden; box-shadow: 0 0 30px rgba(0,0,0,0.8), 0 0 15px ' + specs.primaryColor + '33; border: 2px solid ' + specs.primaryColor + '55; }\n    canvas { display: block; }\n    .hint { margin-top: 0.6rem; font-size: 0.72rem; color: #64748b; font-family: \'JetBrains Mono\', monospace; }\n    .btn { margin-top: 0.4rem; padding: 0.5rem 1.2rem; background: linear-gradient(135deg, ' + specs.gradientStart + ', ' + specs.gradientEnd + '); color: #000; border: none; border-radius: 8px; font-weight: 800; cursor: pointer; text-transform: uppercase; font-size: 0.85rem; }\n  </style>\n</head>\n<body>\n  <div class="hud"><span>' + specs.title + '</span><span>Speed: <b id="spd">0</b> km/h</span><span>Lap: <b id="lap">1</b>/3</span><span>Time: <b id="time">0.0</b>s</span></div>\n  <div class="canvas-wrap"><canvas id="gc" width="500" height="500"></canvas></div>\n  <div class="hint">UP = Accelerate | DOWN = Brake | LEFT/RIGHT = Steer | Complete 3 laps!</div>\n  <button class="btn" onclick="resetRace()">Restart Race</button>\n  ' + aiBadge(specs) + '\n  <script>\n    var c=document.getElementById("gc"),ctx=c.getContext("2d"),spdEl=document.getElementById("spd"),lapEl=document.getElementById("lap"),timeEl=document.getElementById("time"),keys={},cx=250,cy=250,trackR=180,trackW=60;var car={angle:0,speed:0,x:cx+trackR,y:cy};var lap=1,lapAngle=0,prevAngle=0,raceTime=0,raceOver=false;\n    window.addEventListener("keydown",function(e){keys[e.code]=true;e.preventDefault();});window.addEventListener("keyup",function(e){keys[e.code]=false;});\n    var obstacles=[];for(var i=0;i<6;i++){var a=Math.random()*Math.PI*2;var r=trackR+(Math.random()-0.5)*trackW*0.5;obstacles.push({x:cx+Math.cos(a)*r,y:cy+Math.sin(a)*r,r:6});}\n    function update(dt){if(raceOver)return;raceTime+=dt/1000;timeEl.textContent=raceTime.toFixed(1);if(keys.ArrowUp||keys.KeyW)car.speed=Math.min(car.speed+0.15,5);else if(keys.ArrowDown||keys.KeyS)car.speed=Math.max(car.speed-0.2,0);else car.speed*=0.98;if(car.speed>0.5){if(keys.ArrowLeft||keys.KeyA)car.angle-=0.04*(car.speed/3);if(keys.ArrowRight||keys.KeyD)car.angle+=0.04*(car.speed/3);}car.x+=Math.cos(car.angle)*car.speed;car.y+=Math.sin(car.angle)*car.speed;spdEl.textContent=Math.floor(car.speed*40);var distFC=Math.sqrt(Math.pow(car.x-cx,2)+Math.pow(car.y-cy,2));if(distFC>trackR+trackW/2||distFC<trackR-trackW/2)car.speed*=0.9;for(var i=0;i<obstacles.length;i++){var d=Math.sqrt(Math.pow(car.x-obstacles[i].x,2)+Math.pow(car.y-obstacles[i].y,2));if(d<obstacles[i].r+8)car.speed*=0.3;}var carAngle=Math.atan2(car.y-cy,car.x-cx);if(prevAngle<-2.5&&carAngle>2.5)lapAngle-=Math.PI*2;else if(prevAngle>2.5&&carAngle<-2.5)lapAngle+=Math.PI*2;var totalAngle=lapAngle+carAngle;var currentLap=Math.floor(totalAngle/(Math.PI*2))+1;if(currentLap>lap&&currentLap<=3){lap=currentLap;lapEl.textContent=lap;}if(currentLap>3)raceOver=true;prevAngle=carAngle;}\n    function draw(){ctx.clearRect(0,0,c.width,c.height);ctx.strokeStyle="#1a1a2e";ctx.lineWidth=trackW+4;ctx.beginPath();ctx.arc(cx,cy,trackR,0,Math.PI*2);ctx.stroke();ctx.strokeStyle="#252540";ctx.lineWidth=trackW;ctx.beginPath();ctx.arc(cx,cy,trackR,0,Math.PI*2);ctx.stroke();ctx.strokeStyle="#333";ctx.lineWidth=1;ctx.setLineDash([10,10]);ctx.beginPath();ctx.arc(cx,cy,trackR,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle="' + specs.primaryColor + '44";ctx.fillRect(cx+trackR-trackW/2,cy-2,trackW,4);for(var i=0;i<obstacles.length;i++){ctx.fillStyle="#ff005533";ctx.beginPath();ctx.arc(obstacles[i].x,obstacles[i].y,obstacles[i].r,0,Math.PI*2);ctx.fill();ctx.strokeStyle="#ff0055";ctx.lineWidth=1;ctx.stroke();}ctx.save();ctx.translate(car.x,car.y);ctx.rotate(car.angle);ctx.fillStyle="' + specs.primaryColor + '";ctx.shadowColor="' + specs.primaryColor + '";ctx.shadowBlur=12;ctx.fillRect(-12,-7,24,14);ctx.shadowBlur=0;ctx.fillStyle="' + specs.accentColor + '";ctx.fillRect(8,-5,4,4);ctx.fillRect(8,1,4,4);ctx.restore();if(raceOver){ctx.fillStyle="' + specs.primaryColor + '";ctx.font="900 28px Inter";ctx.textAlign="center";ctx.fillText("RACE COMPLETE!",cx,cy-10);ctx.fillStyle="#94a3b8";ctx.font=\'14px "JetBrains Mono"\';ctx.fillText("Time: "+raceTime.toFixed(1)+"s",cx,cy+20);}}\n    var lastT=performance.now();function loop(t){var dt=t-lastT;lastT=t;update(dt);draw();requestAnimationFrame(loop);}function resetRace(){car.angle=0;car.speed=0;car.x=cx+trackR;car.y=cy;lap=1;lapAngle=0;prevAngle=0;raceTime=0;raceOver=false;lapEl.textContent="1";spdEl.textContent="0";timeEl.textContent="0.0";}requestAnimationFrame(loop);\n  <\/script>\n</body>\n</html>';
  }

